import 'package:database/src/sql_database.dart';

/// Type definition for a weekly task id.
typedef WeeklyTaskId = int;

/// {@template weekly_task}
/// Model for a weekly task.
/// {@endtemplate}
class WeeklyTaskModel {
  /// {@macro weekly_task}
  WeeklyTaskModel({
    required this.id,
    required this.title,
    required this.description,
    required this.weight,
    required this.isCompleted,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Creates a new [WeeklyTaskModel] without an ID (for insertion).
  /// The ID will be auto-generated by the database.
  WeeklyTaskModel.create({
    required this.title,
    required this.description,
    required this.weight,
    this.isCompleted = false,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) : id = 0,
       createdAt = createdAt ?? DateTime.now(),
       updatedAt = updatedAt ?? DateTime.now();

  /// Creates a [WeeklyTaskModel] from a a [WeeklyTask] table instance.
  factory WeeklyTaskModel.fromTable(WeeklyTask data) => WeeklyTaskModel(
    id: data.id,
    title: data.title,
    description: data.description,
    weight: data.weight,
    isCompleted: data.isCompleted,
    createdAt: data.createdAt,
    updatedAt: data.updatedAt,
  );

  /// Converts the [WeeklyTaskModel] to a map.
  Map<String, dynamic> toMap() => {
    'id': id,
    'title': title,
    'description': description,
    'weight': weight,
    'isCompleted': isCompleted ? 1 : 0,
    'createdAt': createdAt.millisecondsSinceEpoch ~/ 1000,
    'updatedAt': updatedAt.millisecondsSinceEpoch ~/ 1000,
  };

  /// Copy with method
  WeeklyTaskModel copyWith({
    int? id,
    String? title,
    String? description,
    int? weight,
    bool? isCompleted,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => WeeklyTaskModel(
    id: id ?? this.id,
    title: title ?? this.title,
    description: description ?? this.description,
    weight: weight ?? this.weight,
    isCompleted: isCompleted ?? this.isCompleted,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );

  /// The unique identifier for the task.
  final int id;

  /// The title of the task.
  final String title;

  /// The description of the task.
  final String? description;

  /// The weight of the task.
  final int weight;

  /// Whether the task is completed.
  final bool isCompleted;

  /// The date and time the task was created.
  final DateTime createdAt;

  /// The date and time the task was last updated.
  final DateTime updatedAt;
}
